package com.bank.groupreport;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class FlatMapGroupDemo {
    private static final Logger log = Logger.getLogger("GroupReport");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Department it = new Department(List.of(
            new Employee("Rajesh", "Mumbai", 1000000),
            new Employee("Amit", "Mumbai", 50000)));      // below 60k → excluded
        Department sales = new Department(List.of(
            new Employee("Neha", "Mumbai", 90000),
            new Employee("Priya", "Delhi", 80000)));
        Company bank = new Company(List.of(it, sales));
        GroupReportService service = new GroupReportService();

        Map<String, List<String>> report = service.highEarnersByCity(List.of(bank));
        report.forEach((city, names) -> log.info(() -> city + " → " + names));
    }
}

// ─── Would be in model/Company.java ───
class Company {
    private final List<Department> departments;
    Company(List<Department> departments) { this.departments = departments; }
    List<Department> getDepartments() { return departments; }
}

// ─── Would be in model/Department.java ───
class Department {
    private final List<Employee> employees;
    Department(List<Employee> employees) { this.employees = employees; }
    List<Employee> getEmployees() { return employees; }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String city;
    private final double salary;
    Employee(String name, String city, double salary) {
        this.name = name; this.city = city; this.salary = salary;
    }
    String getName() { return name; }
    String getCity() { return city; }
    double getSalary() { return salary; }
}

// ─── Would be in service/GroupReportService.java ───
class GroupReportService {
    Map<String, List<String>> highEarnersByCity(List<Company> companies) {
        return companies.stream()
            .flatMap(c -> c.getDepartments().stream())     // companies → departments
            .flatMap(d -> d.getEmployees().stream())        // departments → employees
            .filter(e -> e.getSalary() > 60_000)            // high earners
            .collect(groupingBy(Employee::getCity,
                collectingAndThen(
                    mapping(Employee::getName, toList()),    // names per city
                    list -> { Collections.sort(list); return list; }))); // sort each
    }
}
